--liquibase formatted sql

--changeset codex:20261010112645-application-document-checks
-- требование: B3-1…B3-6, FR-35/39/41/43/44/45
alter table package_files add column signature_status varchar(16) not null default 'UNKNOWN';
alter table package_files add column signature_reason varchar(80);
alter table package_files add constraint package_files_signature_status_check
    check (signature_status in ('PRESENT', 'ABSENT', 'UNKNOWN'));

-- Новые версии сохраняют прошлые протоколы, пользовательские правила и пороги/severity/enabled.
with defaults as (select '{"rules": [{"code": "MIN_FIELDS", "title": "Минимум полей вычитан", "op": "REQUIRED_FIELDS", "severity": "WARNING", "fields": {"APPLICATION": ["orgName", "inn", "requestedAmount", "date"], "PD_CONSENT": ["fullName", "date"], "CERTIFICATE": ["number", "validUntil"], "PRESENTATION": ["projectName"], "COST_JUSTIFICATION": ["totalCost", "ownFunds"], "BANK_STATEMENT": ["orgName", "balance", "date"], "PROPERTY_DOC": ["cadastralNumber"], "GUARANTEE_LETTER": ["guarantorName", "amount", "date"], "GIMS_DECLARATION": ["number", "validUntil"]}}, {"code": "INN_FORMAT", "title": "ИНН — 10 или 12 цифр", "op": "PATTERN", "severity": "FAILED", "types": ["*"], "field": "inn", "normalize": "digits", "pattern": "\\d{10}|\\d{12}", "hint": "10 цифр у организации, 12 — у ИП"}, {"code": "INN_SAME", "title": "ИНН одинаков во всех документах", "op": "SAME_VALUE", "severity": "FAILED", "types": ["APPLICATION", "PRESENTATION", "COST_JUSTIFICATION", "BANK_STATEMENT"], "field": "inn", "includeApplicant": true}, {"code": "DATE_NOT_FUTURE", "title": "Дата документа не в будущем", "op": "DATE_NOT_FUTURE", "severity": "FAILED", "types": ["*"], "fields": ["date", "issueDate"]}, {"code": "NOT_EXPIRED", "title": "Срок действия не истёк", "op": "NOT_EXPIRED", "severity": "FAILED", "types": ["CERTIFICATE", "GIMS_DECLARATION"], "field": "validUntil", "warnDays": 30}, {"code": "OWN_FUNDS_SHARE", "title": "Собственные средства не менее 50 % расходов", "op": "RATIO_MIN", "severity": "FAILED", "numerator": ["COST_JUSTIFICATION.ownFunds", "COST_JUSTIFICATION.totalCost - COST_JUSTIFICATION.requestedAmount"], "denominator": ["COST_JUSTIFICATION.totalCost"], "min": "0.50"}, {"code": "REQUEST_MATCH", "title": "Сумма в заявлении совпадает с обоснованием затрат", "op": "EQUAL_SUM", "severity": "FAILED", "pairs": [{"left": "APPLICANT.requestedAmount", "right": "COST_JUSTIFICATION.requestedAmount"}, {"left": "APPLICANT.requestedAmount", "right": "COST_JUSTIFICATION.totalCost - COST_JUSTIFICATION.ownFunds"}, {"left": "APPLICATION.requestedAmount", "right": "COST_JUSTIFICATION.requestedAmount"}, {"left": "APPLICATION.requestedAmount", "right": "COST_JUSTIFICATION.totalCost - COST_JUSTIFICATION.ownFunds"}]}, {"code": "CADASTRAL_FORMAT", "title": "Кадастровый номер в принятом формате", "op": "PATTERN", "severity": "FAILED", "types": ["PROPERTY_DOC"], "field": "cadastralNumber", "normalize": "compact", "pattern": "\\d{2}:\\d{2}:\\d{6,7}:\\d+", "hint": "АА:ВВ:ССССССС:КК, например 61:44:0050706:12"}, {"code": "PRESENTATION_NOT_EMPTY", "title": "Презентация не пустая", "op": "NOT_EMPTY", "severity": "FAILED", "types": ["PRESENTATION"], "fields": ["projectName", "description"]}, {"code": "APPLICATION_INN", "title": "ИНН заявителя соответствует заявке", "op": "APPLICATION_MATCH", "severity": "FAILED", "applicationPath": "orgInn", "fields": {"APPLICATION": ["inn"], "PRESENTATION": ["inn"], "COST_JUSTIFICATION": ["inn"], "BANK_STATEMENT": ["inn"], "CERTIFICATE": ["applicantInn"]}, "normalize": "digits"}, {"code": "APPLICATION_ORG", "title": "Наименование заявителя соответствует заявке", "op": "APPLICATION_MATCH", "severity": "FAILED", "applicationPath": "orgName", "fields": {"APPLICATION": ["orgName"], "PRESENTATION": ["orgName"], "COST_JUSTIFICATION": ["orgName"], "BANK_STATEMENT": ["orgName"], "CERTIFICATE": ["applicantName"], "GIMS_DECLARATION": ["orgName"]}, "normalize": "text"}, {"code": "APPLICATION_OGRN", "title": "ОГРН соответствует заявке", "op": "APPLICATION_MATCH", "severity": "FAILED", "applicationPath": "ogrn", "fields": {"APPLICATION": ["ogrn"]}, "normalize": "digits"}, {"code": "APPLICATION_ADDRESS_LEGAL", "title": "Адрес LEGAL соответствует заявке", "op": "APPLICATION_MATCH", "severity": "FAILED", "applicationPath": "address.value", "fields": {"APPLICATION": ["legalAddress"]}, "normalize": "text", "whenPath": "address.purpose", "whenValue": "LEGAL"}, {"code": "APPLICATION_ADDRESS_ACTUAL", "title": "Адрес ACTUAL соответствует заявке", "op": "APPLICATION_MATCH", "severity": "FAILED", "applicationPath": "address.value", "fields": {"APPLICATION": ["actualAddress"]}, "normalize": "text", "whenPath": "address.purpose", "whenValue": "ACTUAL"}, {"code": "APPLICATION_ADDRESS_PROJECT", "title": "Адрес PROJECT соответствует заявке", "op": "APPLICATION_MATCH", "severity": "FAILED", "applicationPath": "address.value", "fields": {"APPLICATION": ["projectAddress"], "GIMS_DECLARATION": ["address"]}, "normalize": "text", "whenPath": "address.purpose", "whenValue": "PROJECT"}, {"code": "APPLICATION_PLOT", "title": "Участок соответствует заявке", "op": "APPLICATION_MATCH", "severity": "FAILED", "applicationPath": "property.cadastralNumber", "fields": {"PROPERTY_DOC": ["cadastralNumber"]}, "normalize": "compact"}, {"code": "APPLICATION_PROPERTY_ADDRESS", "title": "Адрес участка соответствует заявке", "op": "APPLICATION_MATCH", "severity": "FAILED", "applicationPath": "property.address", "fields": {"PROPERTY_DOC": ["address", "addresses[].address"]}, "normalize": "text"}, {"code": "APPLICATION_OWNER", "title": "Правообладатель соответствует заявителю", "op": "APPLICATION_MATCH", "severity": "FAILED", "applicationPath": "orgName", "fields": {"PROPERTY_DOC": ["rightHolder"]}, "normalize": "text", "whenPath": "property.rightType", "whenValue": "OWNERSHIP"}, {"code": "APPLICATION_TENANT", "title": "Арендатор соответствует заявителю", "op": "APPLICATION_MATCH", "severity": "FAILED", "applicationPath": "orgName", "fields": {"PROPERTY_DOC": ["tenant"]}, "normalize": "text", "whenPath": "property.rightType", "whenValue": "LEASE"}, {"code": "GUARANTEE_BENEFICIARY_INN", "title": "ИНН получателя гарантии соответствует заявителю", "op": "APPLICATION_MATCH", "severity": "FAILED", "applicationPath": "orgInn", "fields": {"GUARANTEE_LETTER": ["beneficiaryInn"]}, "normalize": "digits"}, {"code": "GUARANTEE_BENEFICIARY_NAME", "title": "Получатель гарантии соответствует заявителю", "op": "APPLICATION_MATCH", "severity": "FAILED", "applicationPath": "orgName", "fields": {"GUARANTEE_LETTER": ["beneficiaryName"]}, "normalize": "text"}, {"code": "APPLICATION_REQUEST_MATCH", "title": "Сумма в документе заявки соответствует сохранённой форме", "op": "EQUAL_SUM", "severity": "FAILED", "pairs": [{"left": "APPLICANT.requestedAmount", "right": "APPLICATION.requestedAmount"}]}, {"code": "PDF_SIGNATURE", "title": "Признак ЭП PDF", "op": "SIGNATURE_PRESENCE", "severity": "WARNING", "types": ["*"], "required": false}]}'::jsonb as params),
latest as (select distinct on (code) * from programs
           where code in ('INNOVATION', 'BEACH', 'MODERNIZATION') order by code, version desc)
insert into programs (code, version, name, demo, params, checklist, created_by, created_at)
select latest.code, latest.version + 1, latest.name, latest.demo,
       jsonb_set(latest.params, '{rules}', (
           select jsonb_agg(value order by pos) from (
               select case when replacement.value is null then existing.value
                      else existing.value || (replacement.value - 'min' - 'severity' - 'enabled' - 'tolerance') end as value,
                      existing.pos as pos
               from jsonb_array_elements(coalesce(latest.params->'rules', '[]'::jsonb)) with ordinality existing(value, pos)
               left join lateral (select value from jsonb_array_elements(defaults.params->'rules')
                                  where value->>'code' = existing.value->>'code') replacement on true
               union all
               select value, 1000 + pos from jsonb_array_elements(defaults.params->'rules') with ordinality additions(value, pos)
               where not exists (select 1 from jsonb_array_elements(coalesce(latest.params->'rules', '[]'::jsonb)) old
                                 where old->>'code' = additions.value->>'code')
           ) updated_rules)),
       (select jsonb_agg(case when item->>'kind' = 'CONDITIONAL' and not (item ? 'condition')
                              then item || jsonb_build_object('condition', case when item->'types' ? 'GIMS_DECLARATION'
                                  then 'needsGims' else 'needsCertificate' end) else item end order by pos)
        from jsonb_array_elements(latest.checklist) with ordinality checklist(item, pos)),
       'migration-B3', now()
from latest cross join defaults;

insert into recheck_requests (package_id, due_at, requested_at)
select package_id, now(), now() from package_view where status <> 'DECIDED'
on conflict (package_id) do update set due_at = excluded.due_at, requested_at = excluded.requested_at;

--rollback delete from programs where created_by = 'migration-B3';
--rollback alter table package_files drop column signature_reason;
--rollback alter table package_files drop column signature_status;
